    de:{
      defaults:{before:'Vorher',after:'Nachher',footer:'PictTool · Kostenlose KI-Bildtools'},
      pages:{
        'photo-to-comic':{eyebrow:'KI-Comic-Effekt',h1:'Verwandle dein Foto in eine Comic-Illustration',lead:'Lade ein Portraet oder Alltagsfoto hoch und erstelle einen farbigen Comic-Look, waehrend das Motiv erkennbar bleibt.',primary:'Foto zu Comic testen',secondary:'So funktioniert es',sections:[['Fuer Portraets, Haustiere, Reisen und Profilbilder','Das Comic-Tool von PictTool ist ideal, wenn ein Foto ausdrucksvoller werden soll, ohne das Motiv komplett neu zu gestalten. Klare Fotos mit gutem Licht und sichtbarem Motiv funktionieren am besten.',[['Profilfertiger Stil','Erstelle einen freundlichen Illustrationslook fuer Avatare, Posts und Thumbnails.'],['Erkennbare Details','Der Prompt ist darauf abgestimmt, Gesichter, Kleidung, Pose und Komposition moeglichst zu erhalten.'],['Keine Designsoftware','Hochladen, generieren, ansehen und herunterladen direkt im Browser.']]],['So machst du aus einem Foto Comic-Kunst','',null,[['Waehle ein klares Bild','Nutze ein Portraet, Haustier-, Reise- oder Gruppenfoto mit genug Licht.'],['Oeffne Comic Portrait','Lade das Bild hoch und ergaenze bei Bedarf eine kurze Stilnotiz.'],['Lade das Ergebnis herunter','Speichere den Comic-Look fuer Posts, Pins, Profile oder Kreativmaterial.']],'Comic-Portraet erstellen'],['Foto zu Comic FAQ','',null,null,null,[['Kann ich ein Gruppenfoto verwenden?','Ja. Klare Gruppenfotos koennen funktionieren, nahe Portraets erhalten Gesichtdetails aber meist besser.'],['Welches Foto ist am besten?','Nutze scharfe Bilder mit Motiv nahe der Mitte. Vermeide starke Unschaerfe, dunkles Licht oder sehr kleine Gesichter.'],['Kann ich es kostenlos testen?','PictTool bietet taegliche kostenlose Nutzung mit begrenzten KI-Generierungen.']]]]},
        'remove-background':{eyebrow:'Hintergrund entfernen',h1:'Bildhintergrund online kostenlos entfernen',lead:'Erstelle saubere Freisteller fuer Produkte, Portraets oder Social-Media-Bilder. Lade ein Bild hoch und PictTool entfernt den Hintergrund automatisch.',primary:'Hintergrund entfernen',secondary:'Beste Einsaetze',sections:[['Saubere Freisteller fuer Produkte, Profile und schnelle Designs','Ein transparenter oder einfacher Hintergrund hebt dein Motiv in Shop-Listings, Thumbnails, Profilgrafiken und Social Posts hervor. Der Ablauf ist einfach: hochladen, verarbeiten, herunterladen.',[['Produktfotos','Bereite sauberere Bilder fuer Shops, Kataloge und Promotion vor.'],['Portraets','Trenne eine Person von einem unruhigen Hintergrund, bevor du Poster oder Profilbilder erstellst.'],['Designfertige Dateien','Nutze das Ergebnis in Praesentationen, Posts, Thumbnails und Collagen.']]],['So entfernst du einen Hintergrund','',null,[['Bild hochladen','Waehle JPG, PNG oder WebP mit klarem Hauptmotiv.'],['KI erkennt das Motiv','PictTool trennt Motiv und Hintergrund automatisch.'],['Freisteller herunterladen','Speichere das Ergebnis fuer dein naechstes Design oder Listing.']],'Hintergrundentferner testen'],['Hintergrund entfernen FAQ','',null,null,null,[['Funktioniert es mit Produktfotos?','Ja. Fotos mit klarem Motiv und gutem Kontrast liefern meist die saubersten Freisteller.'],['Brauche ich ein Konto?','Nein. Die grundlegenden kostenlosen Tools koennen ohne Konto getestet werden.'],['Welche Bilder sollte ich vermeiden?','Vermeide sehr unscharfe Fotos, Motive mit aehnlicher Hintergrundfarbe und sehr kleine Details.']]]]},
        'travel-photo-to-art':{eyebrow:'Reisekunst',h1:'Verwandle Reisefotos in illustrierte Kunst',lead:'Mache Sehenswuerdigkeiten, Strassen und Erinnerungen zu Bildern wie illustrierte Postkarten. Lade ein Reisefoto hoch und erstelle eine Kunstversion online.',primary:'Reisekunst erstellen',secondary:'Ideen',sections:[['Mach Reiseerinnerungen teilbarer','Reisefotos haben oft starke Motive, aber normales Licht oder volle Hintergruende. Eine Kunstumwandlung kann ein Wahrzeichen wie Postkarte, Wandbild, Albumcover oder Pinterest-Pin wirken lassen.',[['Postkarten von Orten','Verwandle Tempel, Strassen, Straende und Stadtansichten in illustrierte Andenken.'],['Social Covers','Erstelle auffaellige Bilder fuer Pinterest, Blogs, Reels und Reiseboards.'],['Persoenliche Sammlungen','Baue eine stimmige Reihe kunstvoller Erinnerungen aus verschiedenen Reisen.']]],['So erstellst du Reisefoto-Kunst','',null,[['Waehle ein Reisefoto','Wahrzeichen, Strassenszenen und Aussenfotos mit klaren Formen funktionieren besonders gut.'],['Oeffne Travel Photo to Art','Nutze einen kurzen Prompt wie watercolor postcard, soft ink lines oder illustrated travel poster.'],['Herunterladen und teilen','Nutze das Ergebnis fuer Pin, Blogbild, Albumcover oder Druckidee.']],'Reisekunst testen'],['Reisefoto zu Kunst FAQ','',null,null,null,[['Kann ich Architekturfotos in Kunst verwandeln?','Ja. Gebaeude, Monumente, Strassen und Landschaften funktionieren gut, weil ihre Formen klar sind.'],['Welchen Prompt sollte ich verwenden?','Probiere kurze Prompts wie watercolor postcard, hand-painted travel poster oder soft ink illustration.'],['Kann ich das Ergebnis auf Pinterest nutzen?','Ja, wenn du Rechte am Originalfoto hast. Vorher-Nachher-Reisepins zeigen die Umwandlung besonders gut.']]]]},
        'image-compressor':{eyebrow:'Bildkompressor',h1:'Bilder vor dem Teilen online komprimieren',lead:'Reduziere JPG, PNG und WebP direkt im Browser. So lassen sich Bilder leichter hochladen, mailen, veroeffentlichen und pinnen.',primary:'Bild komprimieren',secondary:'So funktioniert es',metrics:['Originaldatei','Komprimiertes Beispiel','Format vor Download waehlen'],sections:[['Kleinere Dateien fuer Websites, E-Mail und Social Media','Grosse Bilder verlangsamen Uploads und machen Seiten schwerer. Der Kompressor erstellt eine leichtere Version mit ausreichender Qualitaet fuer Online-Nutzung.',[['Blog- und Website-Bilder','Mache Bilder leichter, bevor du sie in einer Seite oder einem Artikel veroeffentlichst.'],['Social Posts','Bereite Bilder fuer Pinterest, Instagram, Facebook und weitere Plattformen vor.'],['Formatkonvertierung','Lade als JPG, PNG oder WebP herunter, je nachdem was du brauchst.']]],['So komprimierst du ein Bild','',null,[['Bild hochladen','Waehle eine JPG-, PNG- oder WebP-Datei von deinem Geraet.'],['Format und Qualitaet waehlen','Niedrigere Qualitaet erzeugt kleinere Dateien; hoehere Qualitaet erhaelt mehr Details.'],['Ergebnis herunterladen','Speichere das komprimierte Bild fuer Orte, an denen du eine leichtere Datei brauchst.']],'Bildkompressor testen'],['Bildkompressor FAQ','',null,null,null,[['Wird das Bild auf einen Server hochgeladen?','Der schnelle Kompressor laeuft im Browser, daher wird das Bild lokal auf deinem Geraet verarbeitet.'],['Welches Format soll ich waehlen?','JPG ist gut fuer Fotos, PNG fuer Transparenz, WebP ist im Web oft kleiner.'],['Verringert Kompression die Qualitaet?','Ja. Kleinere Dateien koennen Details verlieren; waehle die hoechste Qualitaet, die noch eine passende Dateigroesse liefert.']]]]},
        'resize-crop-image':{eyebrow:'Groesse aendern und zuschneiden',h1:'Bilder fuer Social Media zuschneiden',lead:'Erstelle saubere Bildgroessen fuer Pinterest, Instagram, YouTube und mehr. Schneide dein Foto im Browser zu und lade eine teilfertige Version herunter.',primary:'Bild zuschneiden',secondary:'Beliebte Groessen',tags:['Pinterest 2:3','Quadrat 1:1'],sections:[['Ein Bild, viele nuetzliche Formate','Verschiedene Plattformen brauchen unterschiedliche Proportionen. Ein sauberer Zuschnitt haelt das Motiv sichtbar und verhindert unguenstige Schnitte nach dem Upload.',[['Pinterest Pins','Nutze einen hohen Zuschnitt fuer Bilder, die zu Boards und Suche passen.'],['Quadratische Posts','Erstelle einfache 1:1-Zuschnitte fuer Profilbilder, Produktvorschauen und Feeds.'],['Breite Thumbnails','Bereite Querformatbilder fuer YouTube-Cover, Blog-Header und Vorschauen vor.']]],['So aenderst du Groesse und Zuschnitt','',null,[['Foto hochladen','Waehle JPG, PNG oder WebP von deinem Geraet.'],['Seitenverhaeltnis waehlen','Waehle eine gaengige Social-Media-Groesse oder eigene Breite und Hoehe.'],['Zuschnitt herunterladen','Speichere das fertige Bild fuer Post, Pin oder Thumbnail.']],'Zuschneiden testen'],['Resize & Crop FAQ','',null,null,null,[['Wird mein Bild beim Zuschneiden hochgeladen?','Das schnelle Zuschnitt-Tool laeuft lokal im Browser, also bleibt das Bild auf deinem Geraet.'],['Welche Groesse fuer Pinterest?','Ein vertikaler 2:3-Zuschnitt ist ein gaengiger Ausgangspunkt fuer Pins.'],['Kann ich fuer Instagram zuschneiden?','Ja. Quadratische und vertikale Formate sind fuer viele Instagram-Posts nuetzlich.']]]]},
        'product-poster':{eyebrow:'KI-Produktposter',h1:'Verwandle ein Produktfoto in ein Posterbild',lead:'Lade ein Produkt- oder Objektfoto hoch und erstelle ein kommerzielles Visual fuer Pinterest, Shops und Social Posts.',primary:'KI-Poster erstellen',secondary:'Tipps',posterStyle:'Poster-Stil',posterMood:'Saubere Studio-Stimmung',sections:[['Produktposter fuer Shops, Launches und Social Posts','Das KI-Produktposter-Tool verwandelt ein einfaches Produktfoto in ein staerkeres Visual. Das Produkt bleibt Hauptmotiv, waehrend Hintergrund, Licht und Posterkomposition verbessert werden.',[['Posterartiges Ergebnis','Nuetzlich fuer Pinterest, vertikale Posts, Shop-Vorschauen und Launch-Visuals.'],['Produkt bleibt zentral','Der Prompt soll Artikel, Farbe, Material, Verpackung und Gesamtform erhalten.'],['Besserer Kontext','Fuege eine kurze Richtung wie luxury studio, cozy home, clean skincare oder tech launch hinzu.']]],['So erstellst du ein KI-Produktposter','',null,[['Produktbild hochladen','Nutze ein klares Bild mit einfachem Hintergrund oder transparentem Freisteller.'],['Kurze Richtung ergaenzen','Beschreibe Hintergrund, Stimmung oder Zielgruppe, aber vermeide exakte Preise oder langen Text.'],['Ergebnis herunterladen','Speichere das generierte Posterbild und fuege exakten Text spaeter hinzu.']],'KI-Produktposter starten'],['Produktposter FAQ','',null,null,null,[['Schreibt die KI meinen exakten Preis oder Titel?','Nutze KI fuer Hintergrund und visuelle Komposition. Fuege Preise, Markenworte und lange Texte danach hinzu.'],['Welche Bilder funktionieren am besten?','Produktbilder mit klarem Motiv, einfachem Hintergrund und sichtbarer Form funktionieren meist am besten.'],['Verbraucht das KI-Kontingent?','Ja. Es ist ein kreatives KI-Tool und nutzt das Kontingent fuer kreative Bearbeitung.']]]]}
      }
    }
